/// Protocol configuration (simplified)
#[derive(Debug, Clone)]
pub struct ProtocolConfig {
    pub app_id: String,
    /// Local profile selector: which stored identity this instance runs as.
    /// Never on the wire — see `OfflineProtocol::local_address`.
    pub profile: String,
    pub ble_enabled: bool,
    pub wifi_direct_enabled: bool,
    pub internet_enabled: bool,
    pub reticulum_enabled: bool,
    pub nostr_enabled: bool,
    pub prefer_online: bool,
    pub initial_ttl: u8,
    pub encryption_enabled: bool,
    pub auto_key_exchange: bool,
    pub store_pending: bool,
    pub require_encryption: bool,
    pub max_pending_per_peer: u64,
    pub max_pending_global: u64,
    pub pending_ttl_ms: u64,
    pub overflow_policy: OverflowPolicy,
    /// Opt-in (default false): treat a durably-unreachable direct message as
    /// edge-driven after a few reachability probes, instead of probing it
    /// forever at the 15s->600s cap. Zeros steady-state relay traffic to gone
    /// peers and makes a restart skip re-driving a durably-failing backlog, at
    /// the cost of the timed-probe self-recovery guarantee for a silent
    /// returning peer. See the UDL dictionary and
    /// `RetryConfig::edge_driven_unreachable_dm`. Safe only where peers always
    /// interact or advertise presence on return (e.g. machine-to-machine).
    pub edge_driven_unreachable_dm: bool,
    pub max_group_members: u32,
    pub group_relay_enabled: bool,
    /// Whether a relay-synced group may send one O(1) relay broadcast instead
    /// of per-member fan-out (default on, additionally gated on the relay's
    /// `group_delivery_v3` capability). See the UDL dictionary and
    /// `GroupConfig::relay_broadcast_enabled` for why the default is safe.
    pub group_relay_broadcast_enabled: bool,
    /// Whether an unauthorized MLS membership commit is refused rather than
    /// applied-and-reported (default off). See the UDL dictionary and
    /// `GroupConfig::enforce_admin_commits` — enabling this risks permanently
    /// forking members whose admin overlay disagrees.
    pub group_enforce_admin_commits: bool,
    pub require_transport_identity: bool,
    /// Whether a control frame is refused for being stale, and whether a peer
    /// that has proved it signs the freshness-bound payload is held to it
    /// (default on). See the UDL dictionary and
    /// `SecurityConfig::control_freshness_enforced` — the failure it exists to
    /// recover from is this device's own clock, not a peer.
    pub control_freshness_enforced: bool,
    /// Kill switch for the compact binary wire codec (default on). See the UDL
    /// dictionary and `TransportConfig::binary_wire_enabled` for semantics.
    pub binary_wire_enabled: bool,
    /// Kill switch for sealing outgoing Nostr frames into NIP-59 gift wraps
    /// (default on). See the UDL dictionary and
    /// `TransportConfig::nostr_sealing_enabled` — unlike the negotiated
    /// switches, this one is safe to flip on a single device.
    pub nostr_sealing_enabled: bool,
    /// Kill switch for Nostr key-package publication and peer resolution
    /// (default on). See the UDL dictionary and
    /// `TransportConfig::nostr_cold_contact_enabled` for what it buys and what
    /// it costs.
    pub nostr_cold_contact_enabled: bool,
    /// Switch for the username directory (default **off**). See the UDL
    /// dictionary and `TransportConfig::nostr_username_discovery_enabled`.
    ///
    /// Off by default because publishing binds a human-readable name to an
    /// address in a public place, which is materially more disclosure than the
    /// key-package record's "an install with this tag exists". It also requires
    /// cold contact, since a resolved claim dead-ends one hop later without it.
    pub nostr_username_discovery_enabled: bool,
    /// Kill switch for the compact MLS envelope (default on). See the UDL
    /// dictionary and `EncryptionConfig::compact_envelope_enabled` for
    /// semantics.
    pub compact_envelope_enabled: bool,
    /// Kill switch for the sealed rich payload (default on). See the UDL
    /// dictionary and `EncryptionConfig::rich_payload_enabled` for
    /// semantics.
    pub rich_payload_enabled: bool,
    /// Kill switch for 1:1 MLS crypto-failure recovery (default on). See the UDL
    /// dictionary and `EncryptionConfig::crypto_recovery_enabled` for semantics.
    pub crypto_recovery_enabled: bool,
    /// Mesh forwarding tunables. `None` (and any `None` field inside it)
    /// leaves the core default alone — see [`MeshRelayConfig`].
    pub mesh_relay: Option<MeshRelayConfig>,
    /// Whether the replicated-document layer accepts work (default off). See
    /// the UDL dictionary and `DataConfig::enabled` for semantics.
    pub data_enabled: bool,
}

/// Mesh forwarding tunables, every field optional.
